# Parameterized fixed templates; all unprobed templates are explicitly not executed.
queries={
'Q00_tenant_state.cypher':"MATCH (s:TenantState {id:$state,tenant_id:$tenant}) RETURN s.generation,s.epoch,s.authz_epoch,s.schema_version,s.policy_version,s.payload_sha256 LIMIT 2",
'Q01_candidate_identities.cypher':"MATCH (s:TenantState {id:$state,tenant_id:$tenant})-[:COMMITS]->(m:PublicationManifest)<-[:PUBLISHED_BY]-(r:ExperienceRevision)<-[:HAS_REVISION]-(e:Experience) WHERE m.tenant_id=$tenant AND r.tenant_id=$tenant AND e.tenant_id=$tenant AND e.visibility='PUBLIC' AND m.epoch<=s.epoch RETURN DISTINCT e.id ORDER BY e.id LIMIT 257",
'Q02_premise_paths.cypher':"MATCH (s:TenantState {id:$state,tenant_id:$tenant})-[:COMMITS]->(m:PublicationManifest)<-[:PUBLISHED_BY]-(r:ExperienceRevision)<-[:HAS_REVISION]-(e:Experience {id:$experience,tenant_id:$tenant}), (r)-[:USES_RULE]->(rule:Rule)-[:REQUIRES]->(p:Premise) WHERE m.tenant_id=$tenant AND r.tenant_id=$tenant AND rule.tenant_id=$tenant AND p.tenant_id=$tenant AND m.epoch<=s.epoch RETURN r.id,rule.id,p.id,r.payload_json,r.payload_sha256,rule.payload_json,rule.payload_sha256,p.payload_json,p.payload_sha256 ORDER BY r.id,rule.id,p.id LIMIT 1025",
'Q03_supersession_edges.cypher':"MATCH (e:Experience {id:$experience,tenant_id:$tenant})-[:HAS_REVISION]->(r:ExperienceRevision)-[link:SUPERSEDES]->(old:ExperienceRevision) WHERE r.tenant_id=$tenant AND old.tenant_id=$tenant RETURN r.id,old.id,link.id,link.payload_json,link.payload_sha256 ORDER BY r.id,old.id LIMIT 1025",
'Q05_governance_paths.cypher':"MATCH (s:TenantState {id:$state,tenant_id:$tenant})-[:COMMITS]->(m:PublicationManifest)<-[:PUBLISHED_BY]-(g:GovernanceEvent)-[link:GOVERNS]->(target), (e:Experience {id:$experience,tenant_id:$tenant})-[:HAS_REVISION]->(r:ExperienceRevision) WHERE m.tenant_id=$tenant AND g.tenant_id=$tenant AND target.tenant_id=$tenant AND r.tenant_id=$tenant AND m.epoch<=s.epoch AND (target.id=r.id OR target.id IN $evidence_ids) RETURN DISTINCT g.id,g.payload_json,g.payload_sha256,target.id,link.id,m.id ORDER BY g.id,target.id LIMIT 257",
'Q08_current_read_authorization.cypher':"MATCH (s:TenantState {id:$state,tenant_id:$tenant}), (q:Query {id:$query,tenant_id:$tenant}), (session:Session {id:$session,tenant_id:$tenant}) WHERE s.epoch=$epoch AND s.authz_epoch=$authz_epoch AND q.run_id=$run AND q.session_id=session.session_id AND session.run_id=$run RETURN s.epoch,s.authz_epoch,q.id,session.session_id LIMIT 2"}
for name,q in queries.items():(D/'cypher'/name).write_text('// PROPOSED / NOT_EXECUTED; Host params only; payload/manifest verification is mandatory.\n'+q+'\n')
